import{_ as a,o,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"YqlossClientHarmony","description":"","frontmatter":{"title":"YqlossClientHarmony","order":3},"headers":[],"relativePath":"mods/yqlossclientharmony.md","filePath":"mods/yqlossclientharmony.md","lastUpdated":1786957039000}'),l={name:"mods/yqlossclientharmony.md"};function n(i,e,s,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="yqlossclientharmony" tabindex="-1">YqlossClientHarmony <a class="header-anchor" href="#yqlossclientharmony" aria-label="Permalink to &quot;YqlossClientHarmony&quot;">​</a></h1><blockquote><p>Open-source ADOFAI fix, effect removal, and replay Mod.</p><p>Project: <a href="https://github.com/adofaiex/YqlossClientHarmony" target="_blank" rel="noreferrer">https://github.com/adofaiex/YqlossClientHarmony</a></p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>Fix fatal decorations causing failure in no-fail mode</li><li>Fix Set Input events making levels unplayable</li><li>Fix JSON format errors in saved <code>.adofai</code> files</li><li>Prevent accidental game exit</li><li>Play sound effect on game over</li><li><strong>Effect Remover</strong></li><li><strong>Replay</strong></li></ul><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ol><li>Install <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UnityModManager</a></li><li>Download the latest build from <a href="https://github.com/adofaiex/YqlossClientHarmony/releases" target="_blank" rel="noreferrer">Releases</a></li><li>Install via UMM, or extract to <code>A Dance of Fire and Ice/Mods/YqlossClientHarmony/</code></li><li>Launch the game, enable the corresponding features in UMM settings (default <code>Ctrl+F10</code>)</li></ol><h2 id="tutorial-recording-a-replay" tabindex="-1">Tutorial: Recording a Replay <a class="header-anchor" href="#tutorial-recording-a-replay" aria-label="Permalink to &quot;Tutorial: Recording a Replay&quot;">​</a></h2><ol><li>Enable <strong>YCH</strong> and <strong>Replay</strong> (recording) in YCH settings</li><li>Play a level — the replay will be recorded</li></ol><h2 id="tutorial-playing-a-replay" tabindex="-1">Tutorial: Playing a Replay <a class="header-anchor" href="#tutorial-playing-a-replay" aria-label="Permalink to &quot;Tutorial: Playing a Replay&quot;">​</a></h2><ol><li>Enable <strong>YCH</strong> and <strong>Replay</strong> in YCH settings</li><li>Open a level in the level editor, click <strong>Load Replay</strong>, and select a replay file (<code>.ychreplay.gz</code> or <code>.ychreplaygz</code>)</li><li>Adjust game settings to match the recorder&#39;s settings (<strong>except Async Input</strong>)</li><li>Click <strong>Jump to Start</strong> and begin playing</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>&quot;!!!&quot; appears next to the Mod name?</strong></p><p>You may have downloaded a build compiled directly from source. Please download the official release from <a href="https://github.com/adofaiex/YqlossClientHarmony/releases" target="_blank" rel="noreferrer">Releases</a>.</p><p><strong>Planets and floors out of sync during replay?</strong></p><p>Turn off <strong>KeyboardChatterBlocker</strong> during replay.</p><p><strong>KeyboardChatterBlocker incompatible with replay recorder?</strong></p><p>Only certain versions are compatible — the officially tested version is <strong>0.0.10</strong> (0.0.7 is incompatible).</p><p><strong>DLC support?</strong></p><p>DLC support is currently incomplete. If you encounter related issues, please report them in the repository Issues.</p>',19)])])}const u=a(l,[["render",n]]);export{h as __pageData,u as default};
